    Implement fnmatch.fnmatchcase semantics from scratch.

    Supports:
    - * : any run of characters (including empty)
    - ? : exactly one character
    - [seq] : any character in seq
    - [!seq] : any character NOT in seq
    - A ] immediately after [ or [! is a literal ]
    - An unterminated [ is a literal [

    Matching is anchored to the whole string.
    """
    def _parse_bracket(pattern, i):
        """
        Parse a bracket expression starting at pattern[i] where pattern[i] == '['.
        Returns (matched_set, negated, next_index) or None if unterminated (literal [).
        The matched_set is a set of characters that are allowed (if not negated) 
        or disallowed (if negated).
        """
        n = len(pattern)
        i += 1  # skip '['
        negated = False
        if i < n and pattern[i] == '!':
            negated = True
            i += 1

        # Check if ] is immediately after [ or [!
        if i < n and pattern[i] == ']':
            # ] is literal, so it's part of the set
            chars = set()
            chars.add(']')
            i += 1
            # Continue parsing for more characters
            terminated = False
            while i < n:
                if pattern[i] == ']':
                    terminated = True
                    i += 1
                    break
                # Check for range
                if i + 2 < n and pattern[i+1] == '-' and pattern[i+2] != ']':
                    # It's a range
                    start = pattern[i]
                    end = pattern[i+2]
                    if ord(start) <= ord(end):
                        for c in range(ord(start), ord(end) + 1):
                            chars.add(chr(c))
                    i += 3
                else:
                    chars.add(pattern[i])
                    i += 1
            if terminated:
                return (chars, negated, i)
            else:
                # Unterminated
                return None
        else:
            # Normal case: ] is not immediately after [ or [!
            chars = set()
            terminated = False
            while i < n:
                if pattern[i] == ']':
                    terminated = True
                    i += 1
                    break
                # Check for range: pattern[i] == '-' or pattern[i+1] == '-'
                if i + 2 < n and pattern[i+1] == '-' and pattern[i+2] != ']':
                    start = pattern[i]
                    end = pattern[i+2]
                    if ord(start) <= ord(end):
                        for c in range(ord(start), ord(end) + 1):
                            chars.add(chr(c))
                    i += 3
                else:
                    chars.add(pattern[i])
                    i += 1
            if terminated:
                return (chars, negated, i)
            else:
                return None

    def _match(pattern, i, name, j):
        """
        Match pattern[i:] against name[j:].
        Returns True if the rest of the pattern matches the rest of the name.
        """
        n_pat = len(pattern)
        n_name = len(name)

        while i < n_pat:
            c = pattern[i]

            if c == '*':
                # Skip consecutive *
                while i < n_pat and pattern[i] == '*':
                    i += 1
                # If at end of pattern, match succeeds
                if i == n_pat:
                    return True
                # Try matching the rest of the pattern against name[j:], name[j+1:], etc.
                for k in range(j, n_name + 1):
                    if _match(pattern, i, name, k):
                        return True
                return False

            elif c == '?':
                if j >= n_name:
                    return False
                j += 1
                i += 1

            elif c == '[':
                result = _parse_bracket(pattern, i)
                if result is None:
                    # Unterminated [, treat as literal [
                    if j >= n_name or name[j] != '[':
                        return False
                    j += 1
                    i += 1
                else:
                    chars, negated, next_i = result
                    if j >= n_name:
                        return False
                    ch = name[j]
                    if negated:
                        if ch in chars:
                            return False
                    else:
                        if ch not in chars:
                            return False
                    j += 1
                    i = next_i

            else:
                # Literal character
                if j >= n_name or name[j] != c:
                    return False
                j += 1
                i += 1

        # Pattern exhausted; name must also be exhausted
        return j == n_name

    return _match(pattern, 0, name, 0)
