    Match a name against a glob pattern with fnmatch.fnmatchcase semantics.

    Supports:
    - * : any run of characters (including empty)
    - ? : exactly one character
    - [seq] : any character in seq
    - [!seq] : any character NOT in seq
    - ] immediately after [ or [! is a literal ]
    - unterminated [ is a literal [

    The match is anchored to the whole string.
    """

    def _in_bracket(name_char, bracket_content):
        """Check if name_char matches the bracket expression content."""
        # bracket_content is the string between [ and the matching ]
        # First char may be '!' for negation
        negate = False
        start = 0
        if bracket_content.startswith('!'):
            negate = True
            start = 1

        # Handle the case where ] is the first char after [ or [! (literal ])
        # This is already handled by the parser, so bracket_content contains
        # the actual characters/ranges to match against

        matched = False
        i = start
        while i < len(bracket_content):
            # Check for range like a-z
            if (i + 2 < len(bracket_content) and 
                bracket_content[i+1] == '-' and
                i + 2 < len(bracket_content)):
                low = bracket_content[i]
                high = bracket_content[i+2]
                if low <= name_char <= high:
                    matched = True
                    break
                i += 3
            else:
                if name_char == bracket_content[i]:
                    matched = True
                    break
                i += 1

        return not matched if negate else matched

    def _match(pattern, name):
        """
        Recursive match with memoization.
        pattern: remaining pattern to match
        name: remaining name to match
        """
        if not pattern:
            return not name

        # Find the next special character in pattern
        i = 0
        while i < len(pattern):
            if pattern[i] == '*':
                break
            elif pattern[i] == '?':
                break
            elif pattern[i] == '[':
                # Find the matching ]
                j = i + 1
                if j < len(pattern) and pattern[j] == '!':
                    j += 1
                if j < len(pattern) and pattern[j] == ']':
                    j += 1  # ] is literal
                while j < len(pattern) and pattern[j] != ']':
                    j += 1
                if j >= len(pattern):
                    # Unterminated [ is a literal [
                    i += 1
                    continue
                else:
                    break
            else:
                i += 1
        else:
            # No special chars found, all literal
            if len(name) < len(pattern):
                return False
            return name[:len(pattern)] == pattern

        # At this point, pattern[i] is a special char
        if pattern[i] == '*':
            # * matches any run (including empty)
            # Try all possible lengths
            remaining_pattern = pattern[i+1:]
            # Try matching remaining_pattern against name[k:] for k from 0 to len(name)
            for k in range(len(name) + 1):
                if _match(remaining_pattern, name[k:]):
                    return True
            return False
        elif pattern[i] == '?':
            if not name:
                return False
            return _match(pattern[i+1:], name[1:])
        elif pattern[i] == '[':
            # Parse the bracket expression
            j = i + 1
            if j < len(pattern) and pattern[j] == '!':
                j += 1
            if j < len(pattern) and pattern[j] == ']':
                j += 1  # ] is literal, skip it
            while j < len(pattern) and pattern[j] != ']':
                j += 1
            if j >= len(pattern):
                # Unterminated [ is a literal [
                if not name or name[0] != '[':
                    return False
                return _match(pattern[i+1:], name[1:])
            else:
                # j is the index of the closing ]
                bracket_content = pattern[i+1:j]
                if not name:
                    return False
                if _in_bracket(name[0], bracket_content):
                    return _match(pattern[j+1:], name[1:])
                else:
                    return False
        else:
            # This shouldn't happen due to the while loop above, but just in case
            if not name or name[0] != pattern[i]:
                return False
            return _match(pattern[i+1:], name[1:])

    return _match(pattern, name)
