def glob_match(pattern, name):
    """
    Implement fnmatch.fnmatchcase semantics from scratch.
    Supports:
      *   - matches any sequence of characters (including empty)
      ?   - matches any single character
      [seq] - matches any single character in seq
      [!seq] - matches any single character not in seq
      ] immediately after [ or [! is treated as literal
      Unterminated [ is treated as literal [
    Matching is anchored to the whole string.
    """
    import sys

    # We'll use recursive backtracking with memoization to handle * efficiently.
    # State: (pattern_index, name_index)
    # Return: True if pattern[pattern_index:] matches name[name_index:]

    p_len = len(pattern)
    n_len = len(name)

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def match(p, n):
        # p is index into pattern, n is index into name
        if p == p_len:
            return n == n_len

        ch = pattern[p]

        if ch == '*':
            # * matches any sequence of characters
            # Try matching zero or more characters
            # First, skip consecutive *s
            while p < p_len and pattern[p] == '*':
                p += 1
            # Now try to match pattern[p:] against name[n:]
            if p == p_len:
                return True  # rest of pattern is all *s, matches any remaining name
            # Try all possible lengths of the * match
            for i in range(n, n_len + 1):
                if match(p, i):
                    return True
            return False

        elif ch == '?':
            if n < n_len:
                return match(p + 1, n + 1)
            else:
                return False

        elif ch == '[':
            # Parse the bracket expression
            q = p + 1
            negate = False
            if q < p_len and pattern[q] == '!':
                negate = True
                q += 1
            # Check if ] is immediately after [ or [!
            if q < p_len and pattern[q] == ']':
                # ] is literal, so this bracket expression is not a valid bracket
                # Treat [ as literal
                if n < n_len and name[n] == '[':
                    return match(p + 1, n + 1)
                else:
                    return False

            # Parse the bracket expression contents
            # Find the closing ]
            # Note: ] is not special inside unless it's the first char (already handled)
            chars = []
            while q < p_len:
                if pattern[q] == ']':
                    break
                chars.append(pattern[q])
                q += 1

            if q >= p_len:
                # Unterminated [, treat [ as literal
                if n < n_len and name[n] == '[':
                    return match(p + 1, n + 1)
                else:
                    return False

            # q is now at the closing ]
            # Parse the chars list into a set of characters or ranges
            matched_char = False
            if n < n_len:
                c = name[n]
                i = 0
                matched_char = False
                while i < len(chars):
                    if i + 2 < len(chars) and chars[i + 1] == '-':
                        # Range chars[i] - chars[i+2]
                        start = chars[i]
                        end = chars[i + 2]
                        if start <= c <= end:
                            matched_char = True
                            break
                        i += 3
                    else:
                        if c == chars[i]:
                            matched_char = True
                            break
                        i += 1

                if negate:
                    matched_char = not matched_char

            if matched_char:
                return match(p + q + 1, n + 1)
            else:
                return False

        else:
            # Literal character
            if n < n_len and name[n] == ch:
                return match(p + 1, n + 1)
            else:
                return False

    result = match(0, 0)
    match.cache_clear()
    return result
